"use client";

import { useRef, useState } from "react";
import { RiPlayFill, RiPauseFill, RiArrowRightLine } from "react-icons/ri";

type HeroMsgs = {
  title: string;
  tagline: string;
  subtitle: string;
  cta: string;
  ctaHref: string;
  play: string;
  pause: string;
  video?: string;
  poster?: string;
  videoAlt?: string;
};

export default function Hero({ data }: { data: HeroMsgs }) {
  const stars = "/homepage-banner-geospatial-it-bg.jpg";
  // "GIS in Morocco" motion graphic, one file per language (generated by tools/sig-video).
  // Fallback: aerial view of a Moroccan village (Pexels clip 38738429, free commercial use).
  const heroVideo = data.video ?? "/videos/hero-morocco.mp4";
  const posterImg = data.poster ?? "/videos/hero-morocco-poster.jpg";

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(true);

  const togglePlayback = async () => {
    const v = videoRef.current;
    if (!v) return;
    try {
      if (v.paused) {
        await v.play();
        setIsPlaying(true);
      } else {
        v.pause();
        setIsPlaying(false);
      }
    } catch {}
  };

  return (
    <section className="relative text-white">
      <div className="absolute inset-0 bg-black">
        <div
          className="absolute inset-0 opacity-60"
          style={{
            backgroundImage: `url(${stars})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
      </div>

      <div className="relative mx-auto max-w-[1440px] px-4 lg:px-6 py-16 lg:py-24 lg:min-h-[calc(100svh-4rem)] grid gap-12 lg:gap-16 items-center lg:grid-cols-[1.05fr_1fr]">
        <div className="max-w-xl">
          {/* Small brand line above the title strengthens the hierarchy (eyebrow). */}
          <span className="inline-block h-1 w-12 rounded-full bg-[#00a0e3]" aria-hidden />
          <h1 className="mt-6 text-[48px] sm:text-[64px] lg:text-[76px] font-bold leading-[1.02] tracking-[-0.03em]">
            {data.title}
          </h1>
          <p className="mt-4 text-[22px] sm:text-[28px] font-medium leading-snug tracking-[-0.01em] text-white">
            {data.tagline}
          </p>
          <p className="mt-5 text-slate-300 text-[17px] sm:text-[18px] leading-[1.65]">
            {data.subtitle}
          </p>
          <a
            href={data.ctaHref}
            className="group mt-9 inline-flex items-center gap-2 bg-[#0079c1] hover:bg-[#005e95] text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white px-6 py-3.5 text-[15px] font-semibold transition-colors"
          >
            {data.cta}
            <RiArrowRightLine className="h-5 w-5 transition-transform group-hover:translate-x-0.5 motion-reduce:transition-none" aria-hidden />
          </a>
        </div>

        <div className="relative w-full max-w-[560px] justify-self-center lg:justify-self-end">
          <div className="aspect-square overflow-hidden rounded-sm ring-1 ring-white/10 shadow-[0_40px_80px_-30px_rgba(0,160,227,0.35)] bg-black">
            <video
              ref={videoRef}
              src={heroVideo}
              poster={posterImg}
              autoPlay
              muted
              loop
              playsInline
              aria-label={data.videoAlt}
              className="h-full w-full object-cover"
              onPlay={() => setIsPlaying(true)}
              onPause={() => setIsPlaying(false)}
            />
            <div className="absolute right-3 top-3">
              <div className="relative h-9 w-9">
                <div aria-hidden className="absolute -inset-1 rounded-full bg-black/35 backdrop-blur-[1px]" />
                <button
                  type="button"
                  onClick={togglePlayback}
                  aria-label={isPlaying ? data.pause : data.play}
                  className="relative h-9 w-9 flex items-center justify-center rounded-full
                             bg-transparent border-2 border-white text-white
                             hover:bg-white/10 focus:outline-none focus:ring-2 focus:ring-white/40
                             transition [&>*]:pointer-events-none"
                >
                  {isPlaying ? (
                    <RiPauseFill className="h-4 w-4" />
                  ) : (
                    <RiPlayFill className="h-4 w-4 translate-x-[1px]" />
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
